static const float OUT_B[8]={0.0752112f,-0.0573377f,0.0104567f,-0.0318975f,-0.0191034f,-0.0658537f,0.0755552f,0.145847f};
static const float OUT_S=0.000926421f;

struct Vec { float x; float y; };
static const float MAP_W = 16000.0f;
static const float MAP_H = 9000.0f;

static void dense_tanh_q(const int8_t* w, const float* b, float scale, const float* x, float* out, int rows, int cols) {
    for (int r = 0; r < rows; ++r) {
        float sum = b[r];
        const int8_t* wr = w + r * cols;
        float acc = 0.0f;
        for (int c = 0; c < cols; ++c) {
            acc += (float)wr[c] * x[c];
        }
        sum += acc * scale;
        out[r] = tanh(sum);
    }
}

static void dense_linear_q(const int8_t* w, const float* b, float scale, const float* x, float* out, int rows, int cols) {
    for (int r = 0; r < rows; ++r) {
        float sum = b[r];
        const int8_t* wr = w + r * cols;
        float acc = 0.0f;
        for (int c = 0; c < cols; ++c) {
            acc += (float)wr[c] * x[c];
        }
        out[r] = sum + acc * scale;
    }
}

static void build_obs(vector<float>& obs, const vector<Vec>& checkpoints, int laps, int checkpointCount, const array<int,4>& x, const array<int,4>& y, const array<int,4>& vx, const array<int,4>& vy, const array<int,4>& ang, const array<int,4>& nextId, const array<int,4>& lap, const array<int,2>& shieldCd, bool boostAvailable) {
    obs.clear();
    obs.reserve(OBS_SIZE);
    for (int i = 0; i < 4; ++i) {
        float px = (x[i] - MAP_W * 0.5f) / (MAP_W * 0.5f);
        float py = (y[i] - MAP_H * 0.5f) / (MAP_H * 0.5f);
        float vxn = vx[i] / 1000.0f;
        float vyn = vy[i] / 1000.0f;
        float rad = ang[i] * 3.14159265f / 180.0f;
        float c = cos(rad);
        float s = sin(rad);
        Vec cp = checkpoints[nextId[i]];
        float relx = (cp.x - x[i]) / MAP_W;
        float rely = (cp.y - y[i]) / MAP_H;
        float dx = cp.x - x[i];
        float dy = cp.y - y[i];
        float dist = sqrt(dx * dx + dy * dy) / 20000.0f;
        if (dist > 1.0f) dist = 1.0f;
        float lapFrac = laps > 0 ? (float)lap[i] / (float)laps : 0.0f;
        float nextFrac = checkpointCount > 1 ? (float)nextId[i] / (float)(checkpointCount - 1) : 0.0f;
        float shield = 0.0f;
        if (i < 2) shield = shieldCd[i] / 3.0f;
        obs.push_back(px);
        obs.push_back(py);
        obs.push_back(vxn);
        obs.push_back(vyn);
        obs.push_back(c);
        obs.push_back(s);
        obs.push_back(relx);
        obs.push_back(rely);
        obs.push_back(dist);
        obs.push_back(lapFrac);
        obs.push_back(nextFrac);
        obs.push_back(shield);
    }
    obs.push_back(boostAvailable ? 1.0f : 0.0f);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int laps; int checkpointCount;
    if (!(cin >> laps)) return 0;
    cin >> checkpointCount;
    vector<Vec> checkpoints(checkpointCount);
    for (int i = 0; i < checkpointCount; ++i) {
        cin >> checkpoints[i].x >> checkpoints[i].y;
    }

    array<int,4> prevNext; prevNext.fill(-1);
    array<int,4> lap; lap.fill(0);
    array<int,2> shieldCd; shieldCd.fill(0);
    bool boostAvailable = true;

    while (true) {
        array<int,4> x, y, vx, vy, ang, nextId;
        for (int i = 0; i < 4; ++i) {
            if (!(cin >> x[i] >> y[i] >> vx[i] >> vy[i] >> ang[i] >> nextId[i])) {
                return 0;
            }
            if (prevNext[i] == checkpointCount - 1 && nextId[i] == 0) {
                lap[i] += 1;
            }
            prevNext[i] = nextId[i];
        }

        for (int i = 0; i < 2; ++i) {
            if (shieldCd[i] > 0) shieldCd[i] -= 1;
        }

        vector<float> obs;
        build_obs(obs, checkpoints, laps, checkpointCount, x, y, vx, vy, ang, nextId, lap, shieldCd, boostAvailable);

        float h1[H1];
        float h2[H2];
        float out[ACTION_SIZE];
        dense_tanh_q(FC1_W, FC1_B, FC1_S, obs.data(), h1, H1, OBS_SIZE);
        dense_tanh_q(FC2_W, FC2_B, FC2_S, h1, h2, H2, H1);
        dense_linear_q(OUT_W, OUT_B, OUT_S, h2, out, ACTION_SIZE, H2);

        for (int i = 0; i < ACTION_SIZE; ++i) {
            out[i] = tanh(out[i]);
        }

        for (int pod = 0; pod < 2; ++pod) {
            float ax = out[pod * 4 + 0];
            float ay = out[pod * 4 + 1];
            float thrustRaw = out[pod * 4 + 2];
            float special = out[pod * 4 + 3];
            int tx = (int)((ax + 1.0f) * 0.5f * MAP_W);
            int ty = (int)((ay + 1.0f) * 0.5f * MAP_H);
            int thrust = (int)((thrustRaw + 1.0f) * 50.0f);
            if (thrust < 0) thrust = 0;
            if (thrust > 100) thrust = 100;
            if (special > 0.5f && boostAvailable) {
                cout << tx << " " << ty << " BOOST" << '\n';
                boostAvailable = false;
            } else if (special < -0.5f) {
                cout << tx << " " << ty << " SHIELD" << '\n';
                shieldCd[pod] = 3;
            } else {
                cout << tx << " " << ty << " " << thrust << '\n';
            }
        }
    }
    return 0;
}